function rampartSimulate(createStrategy, seed, maxTicks) {
  "use strict";
  var floor = Math.floor;
  var GROUND = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AIR = [[0, 6], [21, 6], [21, 11], [23, 11]];
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8],
               [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var TDEF = {
    bolt:   { cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,
              air: true },
    cannon: { cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,
              air: false },
    frost:  { cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,
              air: true },
    lance:  { cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,
              air: false },
    flak:   { cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false,
              air: true }
  };
  var EDEF = {
    grunt:    { hp: 60,    speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:   { hp: 40,    speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:     { hp: 50,    speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:    { hp: 150,   speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter: { hp: 90,    speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:   { hp: 70,    speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0,    speed: 12, bounty: 1, leak: 1, air: 0, first: 0, weight: 0 }
  };
  var ORDER = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];

  function routeLen(poly) {
    var L = 0;
    for (var i = 1; i < poly.length; i++) {
      L += Math.abs(poly[i][0] - poly[i - 1][0]) + Math.abs(poly[i][1] - poly[i - 1][1]);
    }
    return L * 100;
  }
  function pointAt(poly, p) {
    var rem = p;
    for (var i = 1; i < poly.length; i++) {
      var ax = poly[i - 1][0] * 100 + 50, ay = poly[i - 1][1] * 100 + 50;
      var bx = poly[i][0] * 100 + 50, by = poly[i][1] * 100 + 50;
      var seg = Math.abs(bx - ax) + Math.abs(by - ay);
      if (rem <= seg || i === poly.length - 1) {
        var t = rem < 0 ? 0 : (rem > seg ? seg : rem);
        return { x: ax + (bx - ax) * t / seg, y: ay + (by - ay) * t / seg };
      }
      rem -= seg;
    }
    var last = poly[poly.length - 1];
    return { x: last[0] * 100 + 50, y: last[1] * 100 + 50 };
  }
  var GROUND_LEN = routeLen(GROUND), AIR_LEN = routeLen(AIR);

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }

  // ---------------- setup ----------------
  var strategy = createStrategy();
  var rng = mulberry32(seed >>> 0);

  function genWave(w) {
    var types = [], weights = [], total = 0, i, t;
    for (i = 0; i < ORDER.length; i++) {
      t = EDEF[ORDER[i]];
      if (t.first <= w) { types.push(ORDER[i]); weights.push(t.weight); total += t.weight; }
    }
    var n = 4 + floor(3 * w / 5), out = [];
    for (i = 0; i < n; i++) {
      var r = rng() % total, pick = types[types.length - 1];
      for (var k = 0; k < types.length; k++) {
        if (r < weights[k]) { pick = types[k]; break; }
        r -= weights[k];
      }
      out.push(pick);
    }
    return out;
  }

  var hpMul = [0];
  hpMul[1] = 1000;
  function ensureMul(w) {
    while (hpMul.length <= w) {
      var n = hpMul.length;
      hpMul[n] = floor(hpMul[n - 1] * 108 / 100);
    }
  }

  function tierDmg(base, tier) {
    var d = base;
    for (var i = 1; i < tier; i++) d = floor(d * 16 / 10);
    return d;
  }

  var baseHp = 10, gold = 250;
  var slots = [];
  var enemies = [];        // sorted by id ascending (ids strictly ascending, kept sorted)
  var spawnQueue = [];     // {tick, wave, idx, type}
  var nextId = 1;
  var wave = 0;
  var nextWave = genWave(1);
  var log = [];
  var ended = false, fallTick = -1;
  var tick = 0;
  for (var si = 0; si < 16; si++) slots.push(null);

  function slotXY(s) { return [SLOTS[s][0] * 100 + 50, SLOTS[s][1] * 100 + 50]; }

  function rangeOf(t) { return TDEF[t.type].range + 30 * (t.tier - 1); }
  function dmgOf(t) { return tierDmg(TDEF[t.type].dmg, t.tier); }

  function insertEnemy(e) {
    // insert keeping ascending id
    var i = enemies.length;
    while (i > 0 && enemies[i - 1].id > e.id) i--;
    enemies.splice(i, 0, e);
  }

  function spawnEnemy(type, w, progress) {
    var d = EDEF[type];
    ensureMul(w);
    var maxHp;
    if (type === "splitling") maxHp = Math.max(1, floor(w > 0 && hpMul[w] ? 0 : 0)); // overwritten below
    var e = {
      id: nextId++, type: type, wave: w, progress: progress,
      maxHp: 0, hp: 0, armor: 0, speed: d.speed, air: d.air, bounty: d.bounty, leak: d.leak,
      slow: 0, age: 0, dead: false, x: 0, y: 0, remaining: 0
    };
    if (d.air) e.remaining = AIR_LEN - progress; else e.remaining = GROUND_LEN - progress;
    var p = d.air ? pointAt(AIR, progress) : pointAt(GROUND, progress);
    e.x = p.x; e.y = p.y;
    return e;
  }

  function initEnemyStats(e, maxHp, armor) {
    e.maxHp = maxHp; e.hp = maxHp; e.armor = armor;
  }

  function armorOf(type, w) {
    if (type === "grunt") return floor(w / 4);
    if (type === "brute") return 6 + w;
    return 0;
  }

  function makeSpawn(type, w, progress) {
    var d = EDEF[type];
    ensureMul(w);
    var base = type === "splitling" ? 0 : d.hp;
    var e = spawnEnemy(type, w, progress);
    var maxHp = floor(base * hpMul[w] / 1000);
    initEnemyStats(e, maxHp, armorOf(type, w));
    return e;
  }

  function enemyView(e, range2, tx, ty, checkRange) {
    var v = { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y,
              air: e.air, armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0,
              remaining: e.remaining };
    return v;
  }

  function slotView(s) {
    var t = slots[s];
    var xy = slotXY(s);
    return { slot: s, x: xy[0], y: xy[1],
             turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null };
  }

  function buildState() {
    var ev = [], i;
    for (i = 0; i < enemies.length; i++) { var e = enemies[i]; if (!e.dead) ev.push(enemyView(e)); }
    var sl = [];
    for (i = 0; i < 16; i++) sl.push(slotView(i));
    return { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: sl, enemies: ev, nextWave: nextWave.slice() };
  }

  function applyActions(actions) {
    if (!actions || typeof actions.length !== "number") return;
    var n = Math.min(32, actions.length);
    for (var i = 0; i < n; i++) {
      var a = actions[i];
      if (!a || typeof a !== "object") continue;
      var slot = a.slot, type = a.type, t;
      if (typeof slot !== "number" || slot !== floor(slot) || slot < 0 || slot > 15) continue;
      if (a.op === "build") {
