function createStrategy() {
  var P = (typeof globalThis !== "undefined" && globalThis.STRAT_PARAMS) || {};
  var cfg = {
    starts: P.starts || { "0": "bolt", "1": "flak", "2": "bolt", "4": "frost", "15": "bolt" },
    rv: P.rv || { "1": "cannon", "3": "lance", "5": "bolt", "6": "flak", "7": "bolt", "8": "lance", "9": "flak", "10": "cannon", "11": "lance", "12": "cannon", "13": "lance", "14": "lance" },
    reserve: P.reserve !== undefined ? P.reserve : 0,
    targetGold: P.targetGold !== undefined ? P.targetGold : 400,
    typeBonus: P.typeBonus || { flak: 30, frost: 20, cannon: 10, lance: 0, bolt: 0 },
    maxTier: P.maxTier !== undefined ? P.maxTier : 3,
    upT1: P.upT1 !== undefined ? P.upT1 : 1.0,
    upT2: P.upT2 !== undefined ? P.upT2 : 1.0,
    upT3: P.upT3 !== undefined ? P.upT3 : 1.0
  };
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var RANGE = { bolt: 300, cannon: 260, frost: 240, lance: 360, flak: 320 };
  var AIR = { wisp: 1 };

  function dmgAt(type, tier) { var d = DMG[type]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function rangeAt(type, tier) { return RANGE[type] + 30 * (tier - 1); }
  function covered(slot, type, tier, enemies) {
    var r = rangeAt(type, tier), r2 = r * r, s = 0, sx, sy;
    // slot coordinates from state required; fall back to table below
    sx = SLOTX[slot]; sy = SLOTY[slot];
    for (var i = 0; i < enemies.length; i++) {
      var e = enemies[i];
      if (AIR[e.type] && type === "cannon" || AIR[e.type] && type === "lance") continue;
      if (!AIR[e.type] && type === "flak") continue;
      var dx = e.x - sx, dy = e.y - sy;
      if (dx * dx + dy * dy <= r2) s += 1;
    }
    return s;
  }
  var SLOTX = [350, 550, 750, 750, 950, 1050, 1150, 1350, 1450, 1550, 1650, 1750, 1950, 2050, 2250, 350];
  var SLOTY = [350, 550, 450, 850, 950, 550, 850, 850, 550, 250, 750, 450, 850, 1050, 950, 750];

  function plan(st) {
    var acts = [];
    var gold = st.gold;
    var turrets = [];
    for (var i = 0; i < 16; i++) turrets.push(st.slots[i].turret);
    function place(slot, type) {
      acts.push({ op: "build", slot: slot, type: type });
      gold -= COST[type];
      turrets[slot] = { type: type, tier: 1, spent: COST[type] };
    }
    function up(slot) {
      var t = turrets[slot];
      var c = t.tier === 1 ? COST[t.type] : COST[t.type] * 2;
      acts.push({ op: "upgrade", slot: slot });
      gold -= c;
      t.tier += 1;
    }
    // base starting plan
    var k = String(st.wave);
    if (cfg.starts[k]) {
      var slot = +k, tp = cfg.starts[k];
      if (!turrets[slot] && gold >= COST[tp]) place(slot, tp);
    }
    // air coverage check
    var airCount = 0;
    for (i = 0; i < st.nextWave.length; i++) if (AIR[st.nextWave[i]]) airCount++;
    function airDps() { var d = 0; for (i = 0; i < 16; i++) { var t = turrets[i]; if (t && (t.type === "flak" || t.type === "bolt" || t.type === "frost")) d += dmgAt(t.type, t.tier) / (t.type === "flak" ? 10 : t.type === "bolt" ? 8 : 12); } return d; }
    function rvType(slot) { return cfg.rv[String(slot)] || "bolt"; }

    // Economic / structural decisions first
    var forced = [];
    if (st.wave >= 3) {
      var need = st.wave * 1.0 + 1.5;
      while (airDps() < need && gold >= 80) {
        var bestSlot = -1, bestScore = -1;
        for (i = 0; i < 16; i++) {
          if (turrets[i]) continue;
          var sc = covered(i, "flak", 1, st.enemies);
          if (sc > bestScore) { bestScore = sc; bestSlot = i; }
        }
        if (bestSlot < 0) break;
        place(bestSlot, "flak");
      }
    }
    // build reserved slots
    for (i = 0; i < 16; i++) {
      if (turrets[i]) continue;
      var tp = rvType(i);
      var res = gold - cfg.reserve;
      if (res >= COST[tp]) place(i, tp);
    }
    // upgrades
    var list = [];
    for (i = 0; i < 16; i++) {
      var t = turrets[i];
      if (!t || t.tier >= cfg.maxTier) continue;
      var c = t.tier === 1 ? COST[t.type] : COST[t.type] * 2;
      var eff = dmgAt(t.type, t.tier + 1) - dmgAt(t.type, t.tier);
      var ratio = eff / c;
      var w = t.tier === 1 ? cfg.upT1 : cfg.upT2;
      var cov = covered(i, t.type, t.tier, st.enemies);
      list.push({ i: i, c: c, key: ratio * w * (cov + 1) });
    }
    list.sort(function (a, b) { return b.key - a.key; });
    for (i = 0; i < list.length; i++) {
      if (gold - list[i].c >= cfg.reserve && acts.length < 30) up(list[i].i);
    }
    return acts;
  }

  function target(turret, cands) {
    var best = null, bestScore = 0;
    for (var i = 0; i < cands.length; i++) {
      var e = cands[i];
      var armor = e.armor;
      var eff = dmgAt(turret.type, turret.tier) - (turret.type === "lance" ? 0 : armor);
      if (eff < 1) eff = 1;
      var shots = Math.ceil(e.hp / eff);
      var spd = e.slowed ? Math.floor(e.speed * 60 / 100) : e.speed;
      var exits = Math.floor(e.remaining / Math.max(1, spd));
      var score = 1e9 - exits * 1000 - e.hp;
      if (turret.type === "lance" && e.type === "brute") score += 1e6;
      if (turret.type === "frost") score = (e.slowed ? 0 : 1e6) + (2000 - exits) * 10 + e.hp / 10 + (armor > 10 ? 500 : 0) + (turret.slot === 0 ? 300 : 2);
      score += bestScore - bestScore; // unused
      score += (i === 0 ? 0 : 0);
      if (best === null || score > best.score) best = { id: e.id, score: score };
    }
    return best ? best.id : (cands.length ? cands[0].id : 0);
  }
  return { plan: plan, target: target };
}

