function createStrategy() {
  var P = (typeof globalThis !== "undefined" && globalThis.STRAT_PARAMS) || {};
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var PER = { bolt: 8, cannon: 24, frost: 12, lance: 36, flak: 10 };
  var RANGE = { bolt: 300, cannon: 260, frost: 240, lance: 360, flak: 320 };
  var AIRHIT = { bolt: 1, cannon: 0, frost: 1, lance: 0, flak: 1 };
  var GNDHIT = { bolt: 1, cannon: 1, frost: 1, lance: 1, flak: 0 };
  var AIR = { wisp: 1 };
  var SLOTX = [350, 550, 750, 750, 950, 1050, 1150, 1350, 1450, 1550, 1650, 1750, 1950, 2050, 2250, 2350];
  var SLOTY = [350, 550, 450, 850, 950, 550, 850, 850, 550, 250, 750, 450, 850, 1050, 950, 750];
  // path geometry (centi-tiles), same as the game board
  var PATH = [[50, 250], [650, 250], [650, 1050], [1250, 1050], [1250, 350], [1850, 350], [1850, 1150], [2350, 1150]];
  var PATHS = new Float64Array(13);
  (function () { var acc = 0; PATHS[0] = 0; for (var i = 1; i < PATH.length; i++) { acc += Math.abs(PATH[i][0] - PATH[i - 1][0]) + Math.abs(PATH[i][1] - PATH[i - 1][1]); PATHS[i] = acc; } })();
  var plen = 0;
  for (var q = 0; q < 16; q++) {
    if (AIRHIT[Object.keys(AIRHIT)[0]]) break;
  }
  var cfg = {
    starts: P.starts || { "0": "bolt", "2": "bolt", "4": "frost", "15": "bolt" },
    rv: P.rv || { "1": "flak", "3": "lance", "5": "bolt", "6": "flak", "7": "bolt", "8": "lance", "9": "flak", "10": "cannon", "11": "lance", "12": "cannon", "13": "lance", "14": "lance" },
    reserve: P.reserve !== undefined ? P.reserve : 0,
    upPriority: P.upPriority || { lance: 1.0, cannon: 1.0, flak: 1.0, bolt: 1.0, frost: 0.8 },
    minBuildWave: P.minBuildWave || {},
    airWs: P.airWs || 1.0,
    airK: P.airK || 1.2
  };

  function dmgAt(type, tier) { var d = DMG[type]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function rangeAt(type, tier) { return RANGE[type] + 30 * (tier - 1); }

  // estimate time (ticks) to reach base of a point at distance along path
  function pathPos(p) {
    for (var i = 1; i < PATH.length; i++) {
      if (p <= PATHS[i]) return { x: PATH[i - 1][0] + (PATH[i][0] - PATH[i - 1][0]) * (p - PATHS[i - 1]) / (PATHS[i] - PATHS[i - 1]),
                                   y: PATH[i - 1][1] + (PATH[i][1] - PATH[i - 1][1]) * (p - PATHS[i - 1]) / (PATHS[i] - PATHS[i - 1]) };
    }
    return { x: PATH[PATH.length - 1][0], y: PATH[PATH.length - 1][1] };
  }
  var TOTAL = 4600;

  function plan(st) {
    var acts = [];
    var gold = st.gold;
    var turrets = [];
    var i;
    for (i = 0; i < 16; i++) turrets.push(st.slots[i].turret);
    function place(slot, type) {
      acts.push({ op: "build", slot: slot, type: type });
      gold -= COST[type];
      turrets[slot] = { type: type, tier: 1, spent: COST[type] };
    }
    function up(slot) {
      var t = turrets[slot];
      gold -= (t.tier === 1 ? COST[t.type] : COST[t.type] * 2);
      t.tier += 1;
      acts.push({ op: "upgrade", slot: slot });
    }

    // ---- coverage analytics over the path (tick of arrival per 100 centi-tiles sample)
    var SAMP = 46;
    var cover = [];  // cover[sample] = dps with enemy mix at wave
    var airDps = [];
    var compose = [];
    for (i = 0; i < st.nextWave.length; i++) { var ty = st.nextWave[i]; compose.push({ air: AIR[ty] ? 1 : 0, armor: ty === "brute" ? 6 : 0, slow: st.wave + 1 }); }
    for (i = 0; i < 16; i++) {
      var t = turrets[i];
      if (!t) { continue; }
    }
    // per-turret coverage & value
    function turretValue(i) {
      var t = turrets[i]; if (!t) return 0;
      var r = rangeAt(t.type, t.tier), sx = SLOTX[i], sy = SLOTY[i], dmg = dmgAt(t.type, t.tier);
      var val = 0;
      for (var s = 0; s < SAMP; s++) {
        var px = pathPos((s + 0.5) * TOTAL / SAMP);
        var ddx = px.x - sx, ddy = px.y - sy;
        if (ddx * ddx + ddy * ddy <= r * r) val += 1;
      }
      return val / SAMP;
    }
    // ---- base plan
    var k = String(st.wave), slotK = +k;
    if (cfg.starts[k] && !turrets[slotK] && gold >= COST[cfg.starts[k]]) place(slotK, cfg.starts[k]);

    // ---- air coverage
    function airCover() { var d = 0; for (var j = 0; j < 16; j++) { var t = turrets[j]; if (t && AIRHIT[t.type]) d += dmgAt(t.type, t.tier) / PER[t.type] * turretValue(j); } return d; }
    function airNeed() {
      var n = 0;
      for (var j = 0; j < st.nextWave.length; j++) if (AIR[st.nextWave[j]]) n++;
      return cfg.airWs * (n / Math.max(1, st.nextWave.length)) * (1 + st.wave * 0.12) * cfg.airK;
    }
    while (cfg.minBuildWave.air === undefined || st.wave >= 0) {
      if (airCover() >= airNeed()) break;
      // pick best free slot for a flak
      var bs = -1, bv = -1;
      for (i = 0; i < 16; i++) {
        if (turrets[i]) continue;
        var r = rangeAt("flak", 1), sx = SLOTX[i], sy = SLOTY[i], v = 0;
        for (var s2 = 0; s2 < SAMP; s2++) { var pp = pathPos((s2 + 0.5) * TOTAL / SAMP); var ex = pp.x - sx, ey = pp.y - sy; if (ex * ex + ey * ey <= r * r) v += 1; }
        v *= 1000 - i * 10;
        if (v > bv) { bv = v; bs = i; }
      }
      if (bs < 0 || gold < COST.flak) break;
      place(bs, "flak");
    }

    // ---- build reserved
    for (i = 0; i < 16; i++) {
      if (turrets[i]) continue;
      var tp = cfg.rv[String(i)];
      if (!tp) continue;
      if (cfg.minBuildWave[i] !== undefined && st.wave < cfg.minBuildWave[i]) continue;
      if (gold - cfg.reserve >= COST[tp]) place(i, tp);
    }

    // ---- upgrades by value density
    var cands = [];
    for (i = 0; i < 16; i++) {
      var t3 = turrets[i]; if (!t3) continue;
      var cost = t3.tier === 1 ? COST[t3.type] : COST[t3.type] * 2;
      var gain = dmgAt(t3.type, t3.tier + 1) - dmgAt(t3.type, t3.tier);
      var cov = turretValue(i) * 0.8 + 0.2;
      cands.push({ i: i, cost: cost, key: gain / PER[t3.type] * cov / cost * (cfg.upPriority[t3.type] || 1) });
    }
    cands.sort(function (a, b) { return b.key - a.key; });
    for (i = 0; i < cands.length; i++) {
      if (acts.length >= 30) break;
      if (gold - cands[i].cost >= cfg.reserve) up(cands[i].i);
    }
    return acts;
  }

  function target(turret, cands) {
    var dmg = dmgAt(turret.type, turret.tier);
    var best = null, bs = 0;
    for (var i = 0; i < cands.length; i++) {
      var e = cands[i];
      var eff = turret.type === "lance" ? dmg : dmg - e.armor; if (eff < 1) eff = 1;
      var spd = e.slowed ? Math.floor(e.speed * 60 / 100) : e.speed;
      var sc;
      if (turret.type === "frost") {
        sc = (e.slowed ? 0 : 10000) + (e.armor > 10 ? 500 : 0) + (4600 - e.remaining) * 4 - e.hp * 0.1;
      } else {
        sc = (4600 - e.remaining) * 10 - e.hp * 0.05 + (turret.type === "lance" && e.armor > 30 ? 2000 : 0);
        // avoid overkill: prefer finishing near-dead enemies in the kill zone
        if (e.hp <= eff) sc += 300;
      }
      if (best === null || sc > bs) { best = e; bs = sc; }
    }
