function plan(st) {
  var acts = [];
  var gold = st.gold;
  var turrets = [];
  var i;
  for (i = 0; i < 16; i++) turrets.push(st.slots[i].turret);
  function place(slot, type) {
    acts.push({ op: "build", slot: slot, type: type });
    gold -= COST[type];
    turrets[slot] = { type: type, tier: 1, spent: COST[type] };
  }
  function up(slot) {
    var t = turrets[slot];
    gold -= (t.tier === 1 ? COST[t.type] : COST[t.type] * 2);
    t.tier += 1;
    acts.push({ op: "upgrade", slot: slot });
  }

  // ---- base plan for waves 1..4
  var k = String(st.wave);
  if (cfg.starts[k] && !turrets[+k] && gold >= COST[cfg.starts[k]]) place(+k, cfg.starts[k]);

  // ---- air coverage guarantee
  var airDps = 0;
  for (i = 0; i < 16; i++) {
    var t = turrets[i];
    if (t && AIRHIT[t.type]) airDps += dmgAt(t.type, t.tier) / PER[t.type];
  }
  var need = cfg.airK * (st.wave * 0.5 + 1.0);
  var guard = 0;
  while (st.wave >= 2 && airDps < need && gold >= COST.flak && guard < 4) {
    guard += 1;
    var bSlot = -1, bVal = -1;
    for (var fi = 0; fi < 16; fi++) {
      if (turrets[fi]) continue;
      var fv = coverage(SLOTX[fi], SLOTY[fi], RANGE.flak);
      if (fv > bVal) { bVal = fv; bSlot = fi; }
    }
    if (bSlot < 0) break;
    place(bSlot, "flak");
    airDps += DMG.flak / PER.flak;
  }

  // ---- builds
  for (i = 0; i < cfg.buildOrder.length; i++) {
    var s = cfg.buildOrder[i];
    if (turrets[s]) continue;
    if (s === 0 || s === 2 || s === 4 || s === 15) continue; // handled by base plan
    var type = cfg.typeOrder[String(s)];
    if (!type) continue;
    if (gold - cfg.reserve >= COST[type]) place(s, type);
  }

  // ---- upgrades by dps per gold
  var cands = [];
  for (i = 0; i < 16; i++) {
    var t3 = turrets[i]; if (!t3) continue;
    var cost = t3.tier === 1 ? COST[t3.type] : COST[t3.type] * 2;
    var gain = dmgAt(t3.type, t3.tier + 1) - dmgAt(t3.type, t3.tier);
    cands.push({ i: i, cost: cost, key: gain / PER[t3.type] / cost * (cfg.upPriority[t3.type] || 1) });
  }
  cands.sort(function (a, b) { return b.key - a.key || a.i - b.i; });
  for (i = 0; i < cands.length; i++) {
    if (acts.length >= 30) break;
    if (gold - cands[i].cost >= cfg.reserve) up(cands[i].i);
  }
  return acts;
}

