    // ---- air coverage: anti-air dps must grow with the wave
    var airDps = 0;
    for (var ai = 0; ai < 16; ai++) {
      var at = turrets[ai];
      if (at && AIRHIT[at.type]) airDps += dmgAt(at.type, at.tier) / PER[at.type];
    }
    var need = cfg.airK * (st.wave * 0.5 + 1.0);
