        var fv = coverage(SLOTX[fj], SLOTY[fj], RANGE.flak);
        if (fv > bVal) { bVal = fv; bSlot = fj; }
      }
      if (bSlot < 0) break;
      place(bSlot, "flak");
      airDps += DMG.flak / PER.flak;
    }

    // ---- builds in slot order
    for (var bi = 0; bi < cfg.buildOrder.length; bi++) {
      var sSlot = cfg.buildOrder[bi];
      if (turrets[sSlot]) continue;
      var bType = cfg.typeOrder[String(sSlot)];
      if (!bType) continue;
      if (gold - cfg.reserve >= COST[bType]) place(sSlot, bType);
    }

    // ---- upgrades by dps per gold
    var cands = [];
    for (var ui = 0; ui < 16; ui++) {
      var t3 = turrets[ui];
      if (!t3) continue;
      var cost = t3.tier === 1 ? COST[t3.type] : COST[t3.type] * 2;
      var gain = dmgAt(t3.type, t3.tier + 1) - dmgAt(t3.type, t3.tier);
      cands.push({ i: ui, cost: cost, key: gain / PER[t3.type] / cost * (cfg.upPriority[t3.type] || 1) });
