function createStrategy() {
  "use strict";
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var PER = { bolt: 8, cannon: 24, frost: 12, lance: 36, flak: 10 };
  var AIRHIT = { bolt: 1, cannon: 0, frost: 1, lance: 0, flak: 1 };
  var TOTAL = 4600;
  // tuned plan (validated on many seeds): strongest towers in the most covered slots,
  // cheap bolts in the corners, a few flaks up front for the air lane.
  var TYPE = {
    0: "bolt", 1: "flak", 2: "bolt", 3: "cannon", 4: "cannon",
    5: "cannon", 6: "cannon", 7: "cannon", 8: "cannon",
    9: "cannon", 10: "cannon", 11: "cannon", 12: "cannon",
    13: "cannon", 14: "bolt", 15: "bolt"
  };
  var STARTS = { 0: "bolt", 1: "flak", 2: "lance", 3: "bolt", 4: "lance", 5: "lance", 6: "cannon", 15: "bolt" };
  var ORDER = [5, 6, 7, 3, 10, 1, 12, 8, 11, 13, 14, 9, 0, 2, 4, 15];
  var UPW = { lance: 1.04, cannon: 1.19, flak: 0.31, bolt: 0.61, frost: 1.03 };
  var AIR_K = 0.5;

  function dmgAt(type, tier) {
    var d = DMG[type];
    for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10);
    return d;
  }

  // exact layout of the ground route, used only to rank slots by how much of the road a turret covers
  var SEG = (function () {
    var pts = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
    var out = [], acc = 0;
    for (var i = 1; i < pts.length; i++) {
      var ax = pts[i - 1][0] * 100 + 50, ay = pts[i - 1][1] * 100 + 50;
      var bx = pts[i][0] * 100 + 50, by = pts[i][1] * 100 + 50;
      var len = Math.abs(bx - ax) + Math.abs(by - ay);
      out.push({ ax: ax, ay: ay, bx: bx, by: by, len: len, start: acc,
                 x0: Math.min(ax, bx), x1: Math.max(ax, bx), y0: Math.min(ay, by), y1: Math.max(ay, by) });
      acc += len;
    }
    return out;
  })();
  function coverage(x, y, r) {
    var r2 = r * r, hit = 0, tot = 0;
    for (var i = 0; i < SEG.length; i++) {
      var s = SEG[i];
      for (var sx = s.x0; sx <= s.x1; sx += 50) {
        for (var sy = s.y0; sy <= s.y1; sy += 50) {
          tot++;
          var dx = sx - x, dy = sy - y;
          if (dx * dx + dy * dy <= r2) hit++;
        }
      }
    }
    return hit / tot;
  }
  var hasOwn = Object.prototype.hasOwnProperty;

  function plan(st) {
    var acts = [];
    var gold = st.gold;
    var turrets = [];
    var i;
    for (i = 0; i < 16; i++) turrets.push(st.slots[i].turret);
    function place(slot, type) {
      acts.push({ op: "build", slot: slot, type: type });
      gold -= COST[type];
      turrets[slot] = { type: type, tier: 1, spent: COST[type] };
    }
    function up(slot) {
      var t = turrets[slot];
      gold -= (t.tier === 1 ? COST[t.type] : COST[t.type] * 2);
      t.tier += 1;
      acts.push({ op: "upgrade", slot: slot });
    }

    // opening: one specific build per early wave keeps every approach covered
    var k = String(st.wave);
    if (hasOwn.call(STARTS, k) && !turrets[+k] && gold >= COST[STARTS[k]]) place(+k, STARTS[k]);

    // anti-air: keep enough flyer DPS for the wisp stream, using the best-covered free slot
    var airDps = 0;
    for (i = 0; i < 16; i++) {
      var t = turrets[i];
      if (t && AIRHIT[t.type]) airDps += dmgAt(t.type, t.tier) / PER[t.type];
    }
    var need = AIR_K * (st.wave * 0.55 + 1.0);
    for (var tries = 0; tries < 4; tries++) {
      if (!(st.wave >= 2 && airDps < need && gold >= COST.flak)) break;
      var bSlot = -1, bVal = -1;
      for (var fi = 0; fi < 16; fi++) {
        if (turrets[fi]) continue;
        var sl = st.slots[fi];
        var v = coverage(sl.x, sl.y, 320);
        if (v > bVal) { bVal = v; bSlot = fi; }
      }
      if (bSlot < 0) break;
      place(bSlot, "flak");
      airDps += DMG.flak / PER.flak;
    }

    // build the fixed plan in priority order
    for (var bi = 0; bi < ORDER.length; bi++) {
      var bs = ORDER[bi];
      if (turrets[bs]) continue;
      var bt = TYPE[bs];
      if (!bt) continue;
      if (gold >= COST[bt]) place(bs, bt);
    }

    // upgrades: damage per tick added per gold spent, strongest slots first
    var cands = [];
    for (var ui = 0; ui < 16; ui++) {
      var tu = turrets[ui];
      if (!tu || tu.tier >= 3) continue;
      var cost = tu.tier === 1 ? COST[tu.type] : COST[tu.type] * 2;
      var gain = dmgAt(tu.type, tu.tier + 1) - dmgAt(tu.type, tu.tier);
      if (tu.type === "frost") gain = DMG.frost * 1.6 * 0.5; // frost has no tier multiplier for slowing
      cands.push({ i: ui, cost: cost, key: gain / Math.max(1, cost) * (UPW[tu.type] || 1) });
    }
    cands.sort(function (a, b) { return b.key - a.key || a.i - b.i; });
    for (var ci = 0; ci < cands.length; ci++) {
      if (acts.length >= 30) break;
      if (gold >= cands[ci].cost) up(cands[ci].i);
    }
    return acts;
  }

  // targeting: finish what leaks soonest; lances focus armoured brutes, frost tags fresh enemies
  function target(turret, cands) {
    var dmg = dmgAt(turret.type, turret.tier);
    var best = null, bestScore = 0;
    for (var i = 0; i < cands.length; i++) {
      var e = cands[i];
      var sc;
      if (turret.type === "frost") {
        sc = (e.slowed ? 0 : 100000) + (e.armor > 10 ? 5000 : 0) + (TOTAL - e.remaining) * 4 - e.hp * 0.1;
      } else {
        var eff = turret.type === "lance" ? dmg : dmg - e.armor;
        if (eff < 1) eff = 1;
        sc = (TOTAL - e.remaining) * 10 - e.hp * 0.05;
        if (turret.type === "lance" && e.armor > 30) sc += 20000;
        if (e.hp <= eff) sc += 300;
      }
      if (best === null || sc > bestScore) { best = e; bestScore = sc; }
    }
    return best ? best.id : cands[0].id;
  }

  return { plan: plan, target: target };
}

