// Headless browser check: load index.html, capture console errors, countdown timing, screenshots, fps.
const puppeteer = require('puppeteer-core');
const path = require('path');
const fs = require('fs');
const CHROME = '/Users/rvelez/Library/Caches/ms-playwright/chromium-1223/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const FILE = path.resolve(__dirname, '../../../work/index.html');
const OUT = path.resolve(__dirname, 'shots');
fs.mkdirSync(OUT, { recursive: true });

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME,
    headless: 'new',
    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--autoplay-policy=no-user-gesture-required', '--allow-file-access-from-files']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 650, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type() + ': ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('requestfailed', r => errors.push('reqfail: ' + r.url()));
  await page.goto('file://' + FILE, { waitUntil: 'load', timeout: 60000 });
  const t0 = Date.now();
  await page.waitForFunction(() => window.__RAMPART__ && window.__RAMPART__.state() === 'COUNTDOWN', { timeout: 30000 }).catch(e => errors.push('no state: ' + e.message));
  const samples = [];
  for (let i = 0; i < 14; i++) {
    const s = await page.evaluate(() => ({ st: window.__RAMPART__ && window.__RAMPART__.state(), cd: document.getElementById('countdown').textContent, disp: document.getElementById('countdown').style.display, scrub: document.getElementById('scrubber').value, t: window.__RAMPART__ && window.__RAMPART__.time() }));
    samples.push({ ms: Date.now() - t0, ...s });
    await new Promise(r => setTimeout(r, 250));
  }
  console.log(JSON.stringify(samples, null, 0));
  await page.screenshot({ path: path.join(OUT, 'a_initial.png') });
  // wait until playing
  await page.waitForFunction(() => window.__RAMPART__.state() === 'PLAYING', { timeout: 20000 }).catch(e => errors.push('never playing: ' + e.message));
  // measure fps over 3 s
  const fps = await page.evaluate(() => new Promise(res => { let n = 0; const t = performance.now(); function f() { n++; if (performance.now() - t < 3000) requestAnimationFrame(f); else res(n / ((performance.now() - t) / 1000)); } requestAnimationFrame(f); }));
  console.log('fps', fps);
  await new Promise(r => setTimeout(r, 3000));
  await page.screenshot({ path: path.join(OUT, 'b_playing.png') });
  for (const time of [0, 12.5, 25, 40, 60, 76.85, 77.5, 80, 99.9]) {
    await page.evaluate(t => { document.getElementById('scrubber').value = String(t); document.getElementById('scrubber').dispatchEvent(new Event('input', { bubbles: true })); }, time);
    await new Promise(r => setTimeout(r, 150));
    await page.screenshot({ path: path.join(OUT, 'c_t' + time.toFixed(2) + '.png') });
  }
  const report = await page.evaluate(() => window.BENCH_REPORT);
  console.log('report', JSON.stringify(report));
  console.log('errors', JSON.stringify(errors, null, 1));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

