  const png = require('zlib');
  // decode minimal PNG (RGBA 8-bit, filter 0..4) - simple decoder
  const fs = require('fs');
  const data = fs.readFileSync('tmp_probe.png');
  let pos = 8, width = 0, height = 0, idat = [];
  while (pos < data.length) {
    const len = data.readUInt32BE(pos), type = data.toString('ascii', pos + 4, pos + 8);
    const body = data.slice(pos + 8, pos + 8 + len);
    if (type === 'IHDR') { width = body.readUInt32BE(0); height = body.readUInt32BE(4); }
    if (type === 'IDAT') idat.push(body);
    pos += 12 + len;
  }
  const raw = png.inflateSync(Buffer.concat(idat));
  const bpp = 4, stride = width * bpp + 1;
  const img = Buffer.alloc(width * height * bpp);
  for (let y = 0; y < height; y++) {
    const f = raw[y * stride];
    const row = raw.slice(y * stride + 1, (y + 1) * stride);
    for (let x = 0; x < width * bpp; x++) {
      const a = x >= bpp ? img[y * width * bpp + x - bpp] : 0;
      const b = y > 0 ? img[(y - 1) * width * bpp + x] : 0;
      const c = (x >= bpp && y > 0) ? img[(y - 1) * width * bpp + x - bpp] : 0;
      let v = row[x];
      if (f === 1) v = (v + a) & 255; else if (f === 2) v = (v + b) & 255; else if (f === 3) v = (v + ((a + b) >> 1)) & 255;
