const puppeteer = require('puppeteer-core');
const fs = require('fs');
const CHROME = '/Users/rvelez/Library/Caches/ms-playwright/chromium-1223/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const PAGE = process.env.PAGE || 'index.html';
const OUT = 'shots_ui';
fs.mkdirSync(OUT, { recursive: true });
(async () => {
  const b = await puppeteer.launch({ executablePath: CHROME, headless: 'new', args: ['--no-sandbox', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const p = await b.newPage();
  await p.setViewport({ width: 1280, height: 650 });
  const errs = [];
  p.on('pageerror', e => errs.push(e.message));
  p.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });
  await p.goto('file:///private/tmp/pcd-sbx-deepseek-v4.1-flash-off-r1-ckd2aa7c/work/' + PAGE, { waitUntil: 'load', timeout: 60000 });
  const st = async () => p.evaluate(() => ({ s: document.getElementById('countdown').style.display, t: document.getElementById('countdown').textContent, scrub: document.getElementById('scrubber').value, play: document.getElementById('icon-play').style.display, pause: document.getElementById('icon-pause').style.display, label: document.getElementById('btn-toggle').getAttribute('aria-label') }));
  const log = [];
  await new Promise(r => setTimeout(r, 500));
  log.push(['t0.5s countdown', await st()]);
  // click play during countdown -> PAUSED, countdown hidden, simTime 0
  await p.click('#btn-toggle');
  await new Promise(r => setTimeout(r, 100));
  log.push(['click toggle during countdown', await st()]);
  await new Promise(r => setTimeout(r, 1200));
  log.push(['after 1.2s paused', await st()]);
  // resume: play
  await p.click('#btn-toggle');
  await new Promise(r => setTimeout(r, 1500));
  log.push(['after resume 1.5s', await st()]);
  // speed pill 2.0x
  await p.click('[data-speed="2.0"]');
  log.push(['speed pills', await p.evaluate(() => Array.from(document.querySelectorAll('.speed-pill')).map(x => x.dataset.speed + ':' + x.getAttribute('aria-checked') + ':' + x.classList.contains('is-active')))]);
  await new Promise(r => setTimeout(r, 1000));
  log.push(['after 1s at 2x', await st()]);
  // refire -> hold 1s -> playing
  await p.click('#btn-refire');
  await new Promise(r => setTimeout(r, 200));
  log.push(['refire +0.2s', await st()]);
  await p.evaluate(() => { const e = document.getElementById('countdown'); window.__cdDuringHold = e.style.display + '/' + e.textContent; });
  await new Promise(r => setTimeout(r, 500));
  await p.evaluate(() => { const e = document.getElementById('countdown'); window.__cdDuringHold2 = e.style.display + '/' + e.textContent; });
  await new Promise(r => setTimeout(r, 600));
  log.push(['refire +1.3s', await st()]);
  log.push(['countdown during hold', await p.evaluate(() => [window.__cdDuringHold, window.__cdDuringHold2])]);
  // scrub to 50: input -> paused
  await p.evaluate(() => { const s = document.getElementById('scrubber'); s.value = '50'; s.dispatchEvent(new Event('input', { bubbles: true })); });
  await new Promise(r => setTimeout(r, 100));
  log.push(['scrubbed to 50', await st()]);
  await p.screenshot({ path: OUT + '/scrub50.png' });
  // play to end at 2x from 99
  await p.evaluate(() => { const s = document.getElementById('scrubber'); s.value = '99'; s.dispatchEvent(new Event('input', { bubbles: true })); });
  await p.click('#btn-toggle');
  await new Promise(r => setTimeout(r, 1500));
  log.push(['ended', await st()]);
  await p.screenshot({ path: OUT + '/ended.png' });
  // click toggle at end -> restarts playing from 0
  await p.click('#btn-toggle');
  await new Promise(r => setTimeout(r, 300));
  log.push(['toggle at end', await st()]);
  for (const l of log) console.log(JSON.stringify(l));
  console.log('errors', JSON.stringify(errs));
  await b.close();
})();

